import React, { useState } from "react";

const Header = ({ username, handleLogout, navigate, saveToBackend, fetchResumeList, selectedResume, setSelectedResume, loadSelectedResume }) => {
    const [dropdownOpen, setDropdownOpen] = useState(false);

    return (
        <header className="flex justify-between items-center px-6 py-3 shadow-md bg-white">
            {/* App Title */}
            <h1 className="text-2xl font-bold">Resume Builder</h1>

            {/* Toolbar - Main Actions */}
            <div className="flex gap-3">
                <button className="bg-gray-200 px-4 py-2 rounded-md" onClick={() => navigate("/cover-letter")}>
                    ✍️ Generate Cover Letter
                </button>
                <button className="bg-gray-200 px-4 py-2 rounded-md" onClick={saveToBackend}>
                    💾 Save Progress
                </button>
                <button className="bg-green-600 text-white px-4 py-2 rounded-md" onClick={() => window.location.reload()}>
                    ➕ New Resume
                </button>
            </div>

            {/* Resume Selection */}
            <div className="flex items-center gap-3">
                <select 
                    className="border px-3 py-2 rounded-md"
                    value={selectedResume}
                    onChange={(e) => setSelectedResume(e.target.value)}
                >
                    <option value="">Select a resume</option>
                    {/* Resume List from Backend */}
                    {fetchResumeList.map((resume) => (
                        <option key={resume._id} value={resume.resumeName}>{resume.resumeName}</option>
                    ))}
                </select>

                <button className="bg-blue-600 text-white px-4 py-2 rounded-md" onClick={loadSelectedResume}>
                    📂 Load Resume
                </button>
            </div>

            {/* Profile Dropdown */}
            <div className="relative">
                <button className="flex items-center space-x-2" onClick={() => setDropdownOpen(!dropdownOpen)}>
                    <span className="text-lg">👤</span>
                    <span className="font-semibold">{username || "Guest"}</span>
                </button>

                {/* Dropdown Menu */}
                {dropdownOpen && (
                    <div className="absolute right-0 mt-2 w-48 bg-white shadow-lg rounded-md py-2">
                        {username ? (
                            <>
                                <button className="block w-full text-left px-4 py-2 hover:bg-gray-200" onClick={handleLogout}>
                                    🚪 Logout
                                </button>
                                <button className="block w-full text-left px-4 py-2 hover:bg-gray-200">
                                    ⚙️ Account Settings
                                </button>
                            </>
                        ) : (
                            <button className="block w-full text-left px-4 py-2 hover:bg-gray-200" onClick={() => navigate("/login")}>
                                🔑 Login / Sign Up
                            </button>
                        )}
                    </div>
                )}
            </div>
        </header>
    );
};

export default Header;
